  "vidcfg.durationAutoHint": "自動：モデルが長さを決定します（リファレンス動画を編集する場合はソースクリップの長さ）。クレジットは最長のクリップ分が予約され、実際に出力された長さとの差額が返還されます。",
  "vidcfg.wan3Note": "デフォルトは 720p で 5 秒です（クレジットの見積もりはこの設定に基づきます）。クリップと一緒に環境音が生成されます。「自動調整」は接続された入力に合わせます。テキストのみから動画を生成する場合は、具体的な比率を選択しない限り 16:9 でレンダリングされます。",
  "vidcfg.wan3VideoRefLimits": "Wan 3.0 では、各ソースクリップが 1〜15 秒、接続したクリップの合計が 15 秒以下、入力と出力の長さの合計が 30 秒以下である必要があります。これらはジョブの送信前ではなく、ジョブの実行時にプロバイダー側で確認されます。",
  "vidcfg.wan3AudioRefLimits": "各リファレンスオーディオは 1〜15 秒である必要があり（ジョブの送信前に確認されます）、接続したオーディオの合計は 15 秒以下である必要があります。",
  "vidcfg.matchResSeam": "元の動画の解像度に合わせると、つなぎ目が最もきれいになります。",
