  "vidcfg.veo31Audio": "VEO 3.1 はプロンプトから AI オーディオを生成します。無音の動画にするにはオフにして、「動画とオーディオを結合」ノードを使用してください。",
  "vidcfg.veoAutoTranslateNote": "プロンプトは VEO に渡される前に英語へ自動翻訳されます（デフォルトでオン）。プロンプトをそのまま使うにはオフにしてください。英語以外のプロンプトや、正確な文言が重要な場合（例：パーフェクトループ用のフレーズ）に役立ちます。",
  "vidcfg.veoAutoTranslateNoteShort": "プロンプトは VEO に渡される前に英語へ自動翻訳されます（デフォルトでオン）。プロンプトをそのまま使うにはオフにしてください。",
  "vidcfg.worksBestSameFrames": "開始フレームと終了フレームを同じ画像に固定すると、最もうまく機能します。終了フレームがない場合、アルゴリズムは見つかる中で最適なループポイントを選択しますが、シームレスにならない場合があります。",
