  "audiocfg.descTalkingHeadFaceEnh": "トーキングヘッド動画とオーディオトラックを接続してください。顔補正機能が組み込まれています。",
  "audiocfg.descPortraitTalkingHead": "ポートレート画像とオーディオトラック（音声・ナレーション）を接続すると、トーキングヘッド動画を生成します。",
  "audiocfg.descSingingDiffusion": "動画とオーディオトラックを接続してください。歌唱に最適で、拡散モデルによる高品質なリップシンクを行います。",
  "audiocfg.descFastCheapLipSync": "動画または画像と、オーディオトラックを接続してください。高速で低コストなリップシンクです。",
  "audiocfg.descPortraitNaturalMotion": "ポートレート画像とオーディオを接続すると、自然な動きのトーキングヘッドを生成します。",
  "audiocfg.descAvatarInference": "動画とオーディオトラックを接続すると、高精度なアバター推論によるリップシンクで、音声を差し替えたり吹き替えたりできます。出力 1 秒ごとに課金されます。",
  "audiocfg.descStudioGrade": "スタジオ品質のリップシンクを行うには、動画（.mp4）とオーディオトラック（.wav）を接続してください。出力 1 秒ごとに課金されます。",
  "audiocfg.descSyncSo": "動画とオーディオトラックを接続すると、sync.so v3（fal.ai）で映像を吹き替えます。出力 1 秒ごとに課金されます。",
  "audiocfg.descVolcengine": "動画とオーディオトラックを接続すると、映像を吹き替えます（Volcengine）。出力の長さはオーディオに合わせられます。1 秒ごとに課金されます（約 2 クレジット／秒）。",
  "audiocfg.descVoiceExtractor": "あらゆるオーディオ入力から背景ノイズを除去し、クリアな音声を抽出します。オーディオソース（「オーディオアップロード」「テキストから音声」など）を入力に接続してください。",
  "audiocfg.hintSpeakerBoostDesc": "元の話し方の特徴を強調します。よりドラマチックにしたい場合以外は 0 のままにしてください。値を上げるとレイテンシーが増え、安定性が下がることがあります。",
  "audiocfg.hintSimilarityBoostDesc": "ターゲットのボイスとの類似度を高めます（処理負荷が増え、レイテンシーがわずかに増加します）。デフォルトでオンです。",
  "audiocfg.hintSeedReproducible": "値を固定すると、同じ出力を再現できます（シード、入力、設定がすべて同じ場合）。ランダムにするには空欄のままにしてください。",
  "audiocfg.hintDubCloneDesc": "デフォルトでは、吹き替えで元の話者の声をクローンします。話者は本人の声とアクセントのまま、ターゲット言語で話します。代わりにネイティブらしい似た声を使う場合は、これをオンにしてください。",
