  "tut.regApTitle": "SNS オートパイロット",
  "tut.regApSummary": "アイデアを貼り付けるだけ。7 個のノードがスライドに分割し、スライドごとに画像を描き、キャプションを書いて投稿します。",
  "tut.regApStep1Title": "テキストを 1 つ渡す",
  "tut.regApStep1Sub": "ほかに入力するものはありません",
  "tut.regApStep2Title": "10 枚のスライドを執筆・作画",
  "tut.regApStep2Sub": "スライドごとの文言と画像",
  "tut.regApStep3Title": "キャプションを付けて公開",
  "tut.regApStep3Sub": "フィード用に整えてから投稿",
  "tut.regIedTitle": "画像編集をはじめよう",
  "tut.regIedSummary": "画像を一度だけ生成し、9 つの独立した編集がそれぞれ同じ元画像を読み込みます。編集が積み重ならないので、画質も劣化しません。",
  "tut.regIedNoteEyebrow": "これはチェーンではなく分岐です",
  "tut.regIedNoteBody": "すべての編集が元画像を直接読み込みます。1 つを変更しても、ほかの 8 つには影響しません。それがこの仕組みの要です。",
  "tut.regIedStep1Sub": "一度だけ生成して採点",
  "tut.regIedStep2Title": "1 つのソースから 9 通りの編集",
  "tut.regIedStep2Sub": "どれも同じ画像を読み込みます",
  "tut.regIedStep3Title": "結果をたどる",
  "tut.regIedStep3Sub": "タイルをクリックすると、生成の過程を確認できます",
  "tut.regCcvTitle": "カメラカバレッジ：1 枚のフレーム、10 のアングル",
  "tut.regCcvSummary": "1 枚のリファレンスフレームから、同じシーンの 10 ショットを生成します。変わるのはカメラだけです。1 枚の画像から、そのまま編集でつなげられる、監督のカバレッジプランが完成します。",
  "tut.regCcvChip": "10 ショット",
  "tut.regCcvNoteEyebrow": "鍵はリストにあります",
  "tut.regCcvNoteBody": "画像ノードは 1 つ、行は 10 行。リストで分岐させるので、10 ショットに必要なノードは 25 個ではなく 6 個で済みます。さらに、1 行を編集すれば、そのアングルだけを撮り直せます。",
  "tut.regCcvStep1Sub": "1 枚の画像と、撮影計画を決める指示書",
  "tut.regCcvStep2Sub": "クレジットを使う前に読めて、書き直せる 10 行",
  "tut.regCcvStep3Sub": "1 つの画像ノードから、同じ瞬間の 10 ショット",
  "tut.regOcTitle": "1 人のキャラクターを、どんなシーンにも",
  "tut.regOcSummary": "2 枚のソース画像と、1 行ずつの 5 種類のレシピ。マスクもレイヤーも使いません。結果の違いを生むのは、各ソースのどの部分を指定するか、そしてどの番号で指定するかです。",
  "tut.regOcChip": "5 種類のレシピ",
  "tut.regOcNoteEyebrow": "見るべきは画像ではなく番号",
  "tut.regOcNoteBody": "{image:1} と {image:2} は、ノードの名前ではなく「リファレンス」リスト内の位置（ソースを接続した順番）を表します。レシピ 2 は、レシピ 1 の番号を入れ替えただけのもので、学ぶべきことはそれがすべてです。",
  "tut.regOcStep1Sub": "1 枚は生成、1 枚はアップロード（{image:1} と {image:2}）",
  "tut.regOcStep2Sub": "クリックすると、各ソースから何を取り込み、何を学べるかがわかります",
  "tut.regOcStep3Sub": "画像と、取り込んだパーツがどう組み合わさっているか",
  "tut.regUwTitle": "海中の巨人たち",
  "tut.regUwSummary": "8 つのシーンを書くだけ。各シーンが画像になり、次に 5 秒のショットになって、音楽と合わせて編集され、リールとして投稿されます。",
  "tut.regUwStep1Title": "8 つのシーンを書く",
  "tut.regUwStep1Sub": "それぞれ 1 段落",
  "tut.regUwStep2Title": "静止画から動画へ",
  "tut.regUwStep2Sub": "各シーンは前のシーンを基準に",
  "tut.regUwStep3Title": "音楽付け、編集、投稿",
  "tut.regUwStep3Sub": "34 秒、縦長",
